algorithms.pseudocode:
function CyclotomicBlockQuotient(r):
    require r >= 1
    P <- array of zeros, indices 0 .. 6r-2      # coefficients of degrees 0..6r-2
    for j in 0, 1, ..., r-1:
        base <- 6*j
        P[base + 1] <- P[base + 1] + 1
        P[base + 2] <- P[base + 2] + 2
        P[base + 3] <- P[base + 3] + 2
        P[base + 4] <- P[base + 4] + 1
    return P     # satisfies Phi_6 * P = S_{6r}, all coefficients in {0,1,2}
